TLM.f("Sancti/10-28",{"officium":"Ss. Simonis et Judæ Apostolorum.","rule":["ex C1;","Gloria","Credo","Prefatio=Apostolis"],"ruleInherited":["Psalmi Dominica","Antiphonas horas","Psalm5 Vespera=116","Psalm5 Vespera3=138"],"fallback":"Commune/C1","sections":{"Introitus":[{"k":"ref","la":"Ps 138:17"},{"k":"text","la":"Mihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum."},{"k":"ref","la":"Ps 138:1-2"},{"k":"text","la":"Dómine, probásti me et cognovísti me: tu cognovísti sessiónem meam et resurrectiónem meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Mihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum."}],"Oratio":[{"k":"text","la":"Deus, qui nos per beátos Apóstolos tuos Simónem et Judam ad agnitiónem tui nóminis veníre tribuísti: da nobis eórum glóriam sempitérnam et proficiéndo celebráre, et celebrándo profícere."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Ephésios"},{"k":"ref","la":"Eph 4:7-13"},{"k":"text","la":"Fratres: Unicuíque nostrum data est grátia secúndum mensúram donatiónis Christi. Propter quod dicit: Ascéndens in altum, captívam duxit captivitátem: dedit dona homínibus. Quod autem ascéndit, quid est, nisi quia et descéndit primum in inferióres partes terræ? Qui descéndit, ipse est et qui ascéndit super omnes cœlos, ut impléret ómnia. Et ipse dedit quosdam quidem apóstolos, quosdam autem prophétas, álios vero evangelístas, álios autem pastóres et doctóres, ad consummatiónem sanctórum in opus ministérii, in ædificatiónem córporis Christi: donec occurrámus omnes in unitátem fídei, et agnitiónis Fílii Dei, in virum perféctum, in mensúram ætátis plenitúdinis Christi."}],"Graduale":[{"k":"ref","la":"Ps 44:17-18"},{"k":"text","la":"Constítues eos príncipes super omnem terram: mémores erunt nóminis tui, Dómine."},{"k":"text","la":"Pro pátribus tuis nati sunt tibi fílii: proptérea pópuli confitebúntur tibi. Allelúja, allelúja","mark":"V"},{"k":"ref","la":"Ps 138:17"},{"k":"text","la":"Nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joann 15:17-25"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Hæc mando vobis, ut diligátis ínvicem. Si mundus vos odit: scitóte, quia me priórem vobis odio hábuit. Si de mundo fuissétis, mundus quod suum erat dilígeret; quia vero de mundo non estis, sed ego elegi vos de mundo, proptérea odit vos mundus. Mementóte sermónis mei, quem ego dixi vobis: Non est servus major dómino suo. Si me persecúti sunt, et vos persequántur: si sermónem meum servavérunt, et vestrum servábunt. Sed hæc ómnia fácient vobis propter nomen meum: quia nésciunt eum, qui misit me. Si non veníssem et locútus fuíssem eis, peccátum non háberent: nunc autem excusatiónem non habent de peccáto suo. Qui me odit: et Patrem meum odit. Si ópera non fecíssem in eis, quæ nemo álius fecit, peccátum non háberent: nunc autem et vidérunt et odérunt et me et Patrem meum. Sed ut adimpleátur sermo, qui in lege eórum scriptus est: Quia ódio habuérunt me gratis."}],"Offertorium":[{"k":"ref","la":"Ps 18:5"},{"k":"text","la":"In omnem terram exívit sonus eórum: et in fines orbis terræ verba eórum."}],"Secreta":[{"k":"text","la":"Glóriam, Dómine, sanctórum Apostolórum tuórum Simónis et Judæ perpétuam venerántes: quǽsumus; ut eam, sacris mystériis expiati, dígnius celebrémus."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 19:28"},{"k":"text","la":"Vos, qui secúti estis me, sedébitis super sedes, judicántes duódecim tribus Israël."}],"Postcommunio":[{"k":"text","la":"Percéptis, Dómine, sacraméntis, supplíciter exorámus: ut, intercedéntibus beátis Apóstolis tuis Simóne et Juda, quæ pro illórum veneránda gérimus passióne, nobis profíciant ad medélam."},{"k":"macro","name":"Per Dominum"}]},"hr":{"4ce2969ae90d1d66":{"t":"Ps 138, 17, Ps 138, 1-2\n(Ps 138, 17) Nadasve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove. (Ps 138, 1-2) Gospodine, ti si me kušao i spoznao, tebi je poznat moj počinak i moje uskrsnuće.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 138, 17) Nadasve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove.","kn":"(Ps. 138, 17). Veoma častim prijatelje Tvoje, Bože, silno je utvrđeno kneževstvo njihovo. (Ps. 133, 1). Gospodine, Ti sj me kušao i spoznaoi; Tebi je poznat moj počinak i moje ustajanje. Slava Ocu . . . Veoma ...","knRef":"Kniewald 1942, str. 458–459 (snimka 230) (OCR)"},"a2e4bfdf5ae7e39c":{"t":"<i>Pomolimo se</i>.\nBože, koji si nam dao da po blaženim tvojim apostolima Šimunu i Judi dođemo do spoznaje tvoga imena, daj nam, da napredujući u dobru slavimo njihovu vječnu slavu i slaveći ih da u dobru napredujemo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":", Bože,,, koji -si nam dao, da po blaženim apostolima Tvojim Simonu ; i Judi dođemo do spoznaje. Tvoga imena: daj nam, da napredujući u dobru njihovu vječnu slavu slavimo i slaveći ih da u dobru napredujerho. Po G. nT\"","knRef":"Kniewald 1942, str. 748–749 (snimka 375) (OCR)"},"b813d9523ead8afe":{"t":"Ef 4, 7-13\nČitanje Poslanice bl. Pavla apostola Efežanima. Braćo! Svakom je od nas dana milosti po mjeri Kristova dara. Zato kaže Pismo: Uzašao je na visinu, za sobom je poveo plijen i ljudima je razdijelio darove. Ali što znači da je uzašao, nego da je najprije sišao u donje dijelove zemlje? Koji je sišao, onaj je isti koji je i uzašao nad sve nebo da ispuni sve. I on postavi da jedni budu apostoli, drugi proroci, jedni evanđelisti, drugi pastiri i učitelji; da se sveti usavrše za djelo službe, na sazidanje tijela Kristova, dok svi ne dođemo do jedinstva vjere i spoznaje Sina Božjega, do savršenoga čovjeka, do mjere dobe punine Kristove.","kn":"Čitanje poslanice bi. Pavla apostola Efežanima (4, 7-13). Braćo! Svakom je od nas dana milost. PO mjeri Kristova dara. Zato kaže Pismo; Uzašao je na visinu, sa sobom poveo plijen i ljudima razdijelio đarove.t Mj što znači, da je uzašao, nego da je najprije sišao u do-nje dijelove zemlje? Koji je sišao, -onaj je isti, koji je i uzašao nad sve nebo, da ispuni sve stvari. I on jedne postavi, da budu apostoli, drugi proroci, jedni evanđelisti, drugi pastiri i učitelji, da se sveti usavrše za djelo službe, na sazidanje tijela Kristova, dok svi ne dođemo do jedinstva vjere i spoznaje Sina Božjega, do savršenoga čovjeka, do mjere dobe punine Kristove. '","knRef":"Kniewald 1942, str. 748–749 (snimka 375) (OCR)"},"454bac235247c9f9":{"t":"Ps 44, 17-18\nPostavit ćeš ih za knezove nad svom zemljom, spominjat će tvoje ime, Gospodine. Mjesto tvojih otaca rodit će ti se sinovi, zato će te narodi slaviti.\n\nPs 138, 17\nNada sve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove.","v":"sastavljeno iz dva dijela"},"bbe8fba7412d0efa":{"kn":"† Slijedi sv. evanđelje po Ivanu (15, 17-25).\nU ono vrijeme reče Isus svojim učenicima: Zapovijedam vam, da se ljubite među sobom. Ako vas svijet mrzi, znajte, da je mene mrzio prije nego vas. Kad biste bili od ovoga svijeta, ljubio bi svijet svoje. A jer nijeste od svijeta, nego sam vas ja odijelio od svijeta, zato vas svijet mrzi. Sjetite se, što sam vam rekao: Nije sluga veći od gospodara. Ako su progonili mene, progonit će i vas, ako su održavali moju riječ, održavat će i vašu. A sve će vam ovo činiti radi mene, jer ne poznaju onoga, koji je mene poslao. Kad ne bih bio došao i govorio im, ne bi imali grijeha. Ali sada nemaju izgovora radi svoga grijeha. Tko mrzi mene, mrzi i mojega Oca. Da pred njima nijesam činio djela, kojih nitko drugi ne čini, ne bi imali grijeha. Sada su vidjeli, a ipak mrze i mene i mojega Oca. Ali treba da se ispuni riječ, koja je napisana u njihovu zakonu: Mrzili su me bez uzroka.","knRef":"Kniewald 1942, str. 750-751"},"cb52094c85d2a3b5":{"t":"Ps 18, 5\nPo svoj zemlji iziđe njihov glas i do na kraj svijeta nauka njihova.","kn":"(Ps. 18, 5). Po svoj zemlji iziđe glas njihov i do na kraj zemlje riječi njihove.","knRef":"Kniewald 1942, str. 656–657 (snimka 329) (OCR)"},"3f2f4070deef7720":{"t":"Časteći, Gospodine, vječnu slavu tvojih svetih apostola Šimuna i Jude molimo: da je očišćeni svetim tajnama još dostojnije slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Časteći, Gaspodine, vječnu slavu Tvojih svetih apostola Simona i Jude molimo, da je očišćeni svetim tajnama još dostojnije slavimo, po G. n.","knRef":"Kniewald 1942, str. 750–751 (snimka 376) (OCR)"},"fdbfd5e8960de5c2":{"t":"Uistinu je dostojno, i pravedno, pravo i spasonosno tebe, Gospodine, vječni Pastiru, smjerno moliti da stado svoje ne ostaviš, nego da ga po svojim blaženim apostolima neprestano štitiš i čuvaš, da njime ravnaju isti poglavari, koje si mu postavio na čelo kao pastire i namjesnike svoga djela. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno. Tebe, Gospodine, vječni Pastiru, smjerno moliti, da ne ostaviš svoga stada, nego’ da ga po blaženim svojim apostolima sveudiljnom zaštitom čuvaš, te Tvojim stadom upravljaju isti vođe, koje si Ti odredio da ga vode kao pastiri i namjesnici Tvoga djelovanja. I toga radi pjevamo pjesmu slave Tvoje s anđelima i s arkanđelima, s prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 618–619 (snimka 310) (OCR)"},"4379ab930a0e53cb":{"t":"Mt 19, 28\nVi koji ste pošli za mnom sjedit ćete na prijestoljima i suditi dvanaest plemena Izraelovih.","kn":"(Mt. 19, 28). Vi. koji ste slijedili mene, sjedit ćete na prijestolima sudeći dvanaest plemena Izraelovih,","knRef":"Kniewald 1942, str. 628–629 (snimka 315) (OCR)"},"68a57851df8975f6":{"t":"<i>Pomolimo se</i>.\nPrimivši sveta otajstva smjerno molimo Gospodine, po zagovoru tvojh svetih apostola Šimuna i Jude, da nama koristi za spasenje, što vršimo na spomen njihove časne muke.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primivši svetinje, smjerno molimo. Gospodine, po zagovoru Tvojih svetih apostola Simona i Jude, da nama koristi za spasenje, što činimo za njihovu časnu muku, po G. n. slavi se PO odredbi Pija XI. svake godine u zadnju nedjelju U listopadu.","knRef":"Kniewald 1942, str. 750–751 (snimka 376) (OCR)"}}});
